<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{Check,ChevronRight,Clock3,FilePlus2,GitPullRequest,RefreshCw,ShieldAlert,X}from'lucide-vue-next';import{useAuthStore}from'@/stores/useAuthStore';import{priorityLabel,statusLabel}from'@/features/tickets/ticketsModel';type Step={id:string;name:string;status:string;assignee:string;completedAt?:string};type Event={time:string;actor:string;action:string;comment:string};type Ticket={id:string;title:string;type:string;priority:string;status:string;applicant:string;assignee:string;description:string;createdAt:string;sla:string;risk:string;relatedAsset:string;automationTemplate:string;steps:Step[];timeline:Event[]};type Summary={total:number;pending:number;processing:number;approvedToday:number;slaWarning:number};const auth=useAuthStore(),tickets=ref<Ticket[]>([]),summary=ref<Summary>(),selected=ref<Ticket>(),filter=ref('all'),showCreate=ref(false),loading=ref(false);const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));const visible=computed(()=>filter.value==='all'?tickets.value:tickets.value.filter(x=>x.status===filter.value));async function load(){loading.value=true;[summary.value,tickets.value]=await Promise.all(['summary',''].map(x=>fetch('/api/v1/tickets'+(x?'/'+x:''),{headers:headers.value}).then(r=>r.json())));loading.value=false}async function decide(type:'approve'|'reject'){if(!selected.value)return;await fetch(`/api/v1/tickets/${selected.value.id}/${type}`,{method:'POST',headers:headers.value,body:JSON.stringify({comment:type==='approve'?'审批通过，可以执行':'风险信息不足，请补充'})});await load();selected.value=tickets.value.find(x=>x.id===selected.value?.id)}async function create(){await fetch('/api/v1/tickets',{method:'POST',headers:headers.value,body:JSON.stringify({title:'新增资源申请',type:'resource',priority:'medium',description:'申请新增生产资源并纳入 CMDB'})});showCreate.value=false;await load()}onMounted(load)</script>
<template><section class="tickets-page"><header class="tickets-heading"><div><span>SERVICE REQUEST & APPROVAL</span><h1>工单与审批中心</h1><p>资源申请、变更审批与自动化交付闭环</p></div><div><button @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button><button class="primary" @click="showCreate=true"><FilePlus2/>新建工单</button></div></header><div class="tickets-summary"><article><GitPullRequest/><span>全部工单<strong>{{summary?.total}}</strong></span></article><article><Clock3/><span>待审批<strong>{{summary?.pending}}</strong></span></article><article><RefreshCw/><span>处理中<strong>{{summary?.processing}}</strong></span></article><article><Check/><span>今日通过<strong>{{summary?.approvedToday}}</strong></span></article><article><ShieldAlert/><span>SLA 预警<strong>{{summary?.slaWarning}}</strong></span></article></div><div class="ticket-workspace"><aside class="ticket-filters"><h3>工作台</h3><button v-for="f in [{id:'all',n:'全部工单'},{id:'pending',n:'待我审批'},{id:'processing',n:'处理中'},{id:'approved',n:'已通过'}]" :key="f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{f.n}}<ChevronRight/></button><h3>工单类型</h3><span>资源申请</span><span>变更工单</span><span>故障处理</span></aside><main class="ticket-list"><header><span>工单信息</span><span>优先级</span><span>状态</span><span>处理人 / SLA</span></header><button v-for="x in visible" :key="x.id" :class="{selected:selected?.id===x.id}" @click="selected=x"><div><small>{{x.id}} · {{x.type}}</small><strong>{{x.title}}</strong><span>{{x.applicant}} · {{x.createdAt}}</span></div><b :data-priority="x.priority">{{priorityLabel(x.priority)}}</b><em :data-status="x.status">{{statusLabel(x.status)}}</em><div><strong>{{x.assignee}}</strong><span>{{x.sla}}</span></div></button></main><aside class="ticket-detail"><template v-if="selected"><header><div><span>APPROVAL FLOW</span><h2>{{selected.title}}</h2><small>{{selected.id}}</small></div><button @click="selected=undefined"><X/></button></header><p>{{selected.description}}</p><div class="risk-row"><span>变更风险 <b :data-risk="selected.risk">{{selected.risk}}</b></span><span>关联资产 <b>{{selected.relatedAsset||'—'}}</b></span></div><h3>审批流程</h3><div class="approval-steps"><article v-for="s in selected.steps" :key="s.id" :data-status="s.status"><i><Check v-if="s.status==='completed'"/></i><div><strong>{{s.name}}</strong><span>{{s.assignee}} {{s.completedAt}}</span></div></article></div><h3>处理记录</h3><div class="ticket-timeline"><article v-for="e in selected.timeline" :key="e.time+e.action"><time>{{e.time}}</time><div><strong>{{e.actor}} · {{e.action}}</strong><span>{{e.comment}}</span></div></article></div><footer v-if="selected.status==='pending'"><button @click="decide('reject')">驳回</button><button class="primary" @click="decide('approve')">审批通过</button></footer><a v-if="selected.automationTemplate&&selected.status==='approved'" href="/jobs">进入自动化任务中心执行 →</a></template><div v-else class="empty-ticket"><GitPullRequest/><strong>选择工单</strong><span>查看审批流与处理记录</span></div></aside></div><div v-if="showCreate" class="ticket-modal" @click.self="showCreate=false"><form @submit.prevent="create"><h2>新建资源申请</h2><label>标题<input value="新增资源申请"></label><label>申请说明<textarea>申请新增生产资源并纳入 CMDB</textarea></label><footer><button type="button" @click="showCreate=false">取消</button><button class="primary">提交申请</button></footer></form></div></section></template>
